def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]
    opp_moves = [o for _, o in history]
    opp_defects = opp_moves.count('D')

    # If opponent never defected, cooperate until the very end, then exploit.
    if opp_defects == 0:
        if n >= 98:
            return 'D'
        return 'C'

    # Recent window for opponent defection rate
    recent = history[-10:] if n >= 10 else history
    recent_opp_d = sum(1 for _, o in recent if o == 'D')

    # Alternating cycle break: if last 4 rounds are alternating (C,D),(D,C),(C,D),(D,C) or similar
    if n >= 4:
        last4 = history[-4:]
        if (last4[0] == last4[2] and last4[1] == last4[3] and 
            last4[0] != last4[1]):
            if opp_last == 'D' and my_last == 'C':
                return 'C'

    defect_rate = opp_defects / n

    if opp_last == 'D':
        if recent_opp_d >= 6:
            return 'D'
        if defect_rate > 0.6:
            if rng.random() < 0.05:
                return 'C'
            return 'D'
        else:
            if rng.random() < 0.25:
                return 'C'
            return 'D'
    else:
        if defect_rate < 0.3:
            if n >= 98:
                return 'D'
            return 'C'
        if rng.random() < 0.85:
            return 'C'
        return 'D'
